WITH valid_payments AS (SELECT *, ROUND(amount, 0) amount_rounded FROM payments WHERE amount >= 1090 AND amount BETWEEN 1570 AND 1590), payments_stats AS (SELECT status, COUNT(CASE WHEN method = 'bank_transfer' THEN 1 END) bank_transfer_count, COUNT(amount) amount_count FROM valid_payments GROUP BY status) SELECT status, bank_transfer_count FROM payments_stats WHERE bank_transfer_count > 7 ORDER BY status
